    {
      "subject": "English cue and sense",
      "conclusion": "The cue confused and sense unable to understand or decide clearly are appropriately aligned.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/bingung",
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=keliru"
      ]
    },
    {
      "subject": "Indonesian answer: bingung",
      "conclusion": "Correct and idiomatic Indonesian for being confused, unclear, or not understanding.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/bingung"
      ]
    },
    {
      "subject": "Malaysian Malay answer: keliru",
      "conclusion": "Correct and characteristic Malaysian Malay choice for mistaken or confused understanding.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=keliru"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "Different-common-word is acceptable as a preference-based contrast, provided it is not interpreted as exclusivity; bingung is also attested in Malaysian Malay.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=10456&keyword=bingung",
